INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chibi-Robo!: Park Patrol', 'A pollution epidemic is killing off flowers and ravaging parks worldwide. To combat this threat, Citrusoft Robotics has developed an eco-friendly model of Chibi-Robo and sent it to parks everywhere. As Chibi-Robo, players restore their local park to its former glory by raising flowers and plants, building park equipment and defeating toxic enemies called Smoglings.' FROM games WHERE igdb_id = 21307 ON CONFLICT (game_id, language_code) DO NOTHING;
