INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic and the Secret Rings', 'Sonic and the Secret Rings is a three-dimensional platform and action game featuring an on-rails style of movement. Sonic the Hedgehog, the series'' main character, is the game''s only player character. He is controlled exclusively with the Wii Remote, which is held horizontally like a traditional gamepad.' FROM games WHERE igdb_id = 5167 ON CONFLICT (game_id, language_code) DO NOTHING;
