INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brothers in Arms DS', 'Brothers In Arms DS brings all the action and strategy of the series to a handheld, utilizing the DS Touch Screen to control the squad. Fight in 16 different missions and use a wide range of weapons such as bazookas, sniper rifles, and grenades, or fight in major multiplayer battles with three of your friends in different multiplayer modes.' FROM games WHERE igdb_id = 21422 ON CONFLICT (game_id, language_code) DO NOTHING;
