INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts Re:Chain of Memories', 'Kingdom Hearts Re:Chain of Memories is a full remake of Kingdom Hearts: Chain of Memories, released on the PlayStation 2. In Japan, it is part of the Kingdom Hearts II Final Mix+ compilation and has connectivity features with Kingdom Hearts II Final Mix. As there were no plans to release Kingdom Hearts II Final Mix internationally, these features were modified for the North American release.' FROM games WHERE igdb_id = 20286 ON CONFLICT (game_id, language_code) DO NOTHING;
