INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The World Ends with You', 'In the game, Neku Sakuraba and his allies are forced to participate in a game that will determine their fate. The battle system uses many of the unique features of the Nintendo DS, including combat that takes place on both screens, and attacks performed by certain motions on the touchscreen or by shouting into the microphone. Elements of Japanese youth culture, such as fashion, food, and cell phones, are key aspects of the missions.' FROM games WHERE igdb_id = 1343 ON CONFLICT (game_id, language_code) DO NOTHING;
