INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy Tactics A2: Grimoire of the Rift', 'School is out for the summer, but mischievous Luso Clemens must first face detention to make up for his misbehavior. Alone in the library, he stumbles upon an ancient book with magical powers that summons him to the mystical land of Ivalice. Warped into the middle of a battlefield, Luso joins Cid and his clan to set off on an adventurous journey looking for a way home.' FROM games WHERE igdb_id = 2408 ON CONFLICT (game_id, language_code) DO NOTHING;
