INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snakeball', 'Snakeball & trade; is a funky, futuristic sport set in a vibrant arena where you glide across the dazzling disco floor on your hoversnake, collecting balls and scoring goals. Watch out for the other snakeballers desperate to knock you for a spin with a flick of their tails or a blast from their fiendish weapons. Chaotic action and energetic music bring together up to 8 players in entertaining online matches for a fun, unique gameplay experience.' FROM games WHERE igdb_id = 21881 ON CONFLICT (game_id, language_code) DO NOTHING;
