INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soldier of Fortune: Payback', 'Soldier of Fortune: Payback is a first-person shooter video game and the third installment of the Soldier of Fortune game series. Unlike the previous two Soldier of Fortune games, which were developed by Raven Software utilizing the Quake 2 and Quake 3 engines, Payback was developed by Cauldron HQ, developed with Cauldron''s in-house CloakNT engine, used in their previous first person shooter game, Chaser. It is the first game of the series released for the Xbox 360 and PlayStation 3. The game was released on 14 November 2007.' FROM games WHERE igdb_id = 3113 ON CONFLICT (game_id, language_code) DO NOTHING;
