INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chessmaster-the-art-of-learning', 20777, '2007-10-23', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qtf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rsf0ccxweuenn6nvulun.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chessmaster: The Art of Learning', 'Chessmaster: The Art of Learning expands the scope of chess to include broader principles of learning. Josh Waitzkin''s much-anticipated book The Art of Learning (Free Press) is designed to pave the road to successful long-term growth on and off the chessboard. The eight-time National Chess Champion and two-time martial arts World Champion puts users in his shoes in some of the most riveting and formative moments of his chess career, including the legendary climactic game from the book and film Searching for Bobby Fischer. Waitzkin then turns to the classics, introducing beginners to brilliant games from some of the most important players in the history of chess. In his most revealing commentary ever, Waitzkin not only teaches the beginning chess player the fundamentals of the game, but also humanizes the road to mastery. Never has chess been so exciting.' FROM games WHERE igdb_id = 20777 ON CONFLICT (game_id, language_code) DO NOTHING;
