INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire Rain', 'Vampire Rain is a survival horror stealth video game developed by Artoon. It was released for the Xbox 360 in Japan on January 25, 2007 and in North America on July 3, 2007. The game was later ported to the PlayStation 3 under the title Vampire Rain: Altered Species and was released in Japan on August 21, 2008 and in North America on September 2, 2008.' FROM games WHERE igdb_id = 7231 ON CONFLICT (game_id, language_code) DO NOTHING;
