INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Series of Poker 2008: Battle for the Bracelets', 'World Series of Poker 2008: Battle for the Bracelets is a video game based on the popular gambling tournament World Series of Poker. It is the sequel to World Series of Poker: Tournament of Champions and is available for the Xbox 360, PlayStation 2, PlayStation 3, PlayStation Portable, Nintendo DS and PC. There are many well-recognized professional poker players in this game, such as Scotty Nguyen, Phil Hellmuth, Chris Ferguson, and Johnny Chan.' FROM games WHERE igdb_id = 5289 ON CONFLICT (game_id, language_code) DO NOTHING;
