INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dementium-the-ward', 21238, '2007-10-31', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j8b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/thzfs4yzrq5fgmzc5vyk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dementium: The Ward', 'Dementium - The Ward is a mature-themed first-person shooter/survival horror game for the Nintendo DS that tells the tale of a man who awakens to find himself alone in a mysterious, derelict hospital that is frozen in time. Confronted by the deadly, grotesque surgical experiments that wander the halls, a series of challenging puzzles and a cast of peculiar characters, he must face his deepest fears, unlock the mysteries of the hospital, and escape with his life. The Ward offers a completely new experience on the Nintendo DS and pushes the platform to its limits with full 3D visuals and bone-chilling audio that brings the world screaming to life.' FROM games WHERE igdb_id = 21238 ON CONFLICT (game_id, language_code) DO NOTHING;
