INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince of Persia Classic', 'Prince of Persia Classic is a remake of the original 1989 title, often referred to as the game that kick-started the platforming genre. This new version features updated character designs, animations, visuals, and lighting effects, all transforming the game into a fresh, close to 3-dimensional look. New traps, puzzles, enemies, and achievements have been added.' FROM games WHERE igdb_id = 21797 ON CONFLICT (game_id, language_code) DO NOTHING;
