INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stuntman: Ignition', 'Stuntman: Ignition is the next installment in the Stuntman franchise. The game plunges gamers into the adrenaline-fueled role of a Hollywood stunt driver, challenging them to pull off the most breathtaking, death-defying stunts ever filmed. Players showcase their skills in a wide variety of big-budget action films, commercial shoots and tournaments while commanding more than 25 unique vehicles, including exotic sports cars, motorcycles and hovercraft.' FROM games WHERE igdb_id = 2783 ON CONFLICT (game_id, language_code) DO NOTHING;
