INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Order of the Phoenix', 'Harry Potter and the Order of the Phoenix is the fifth installment of the popular Harry Potter series. Players take control of Harry Potter in this 3D adventure as he faces the dangers of his fifth year of Hogwarts, avoiding the malicious Professor Dolores Umbridge, builds Dumbledore''s Army, and faces off with Voldemort himself as the prophecy continues to unfold. Players will navigate through the castle of Hogwarts and beyond, learning fifth year spells, solving multiple puzzles, avoiding traps, and even get a chance to play as the Weasley brothers, Sirius Black and Dumbledore himself. All versions are the same with the exception of the Wii. Players can use the Wiimote as Harry''s wand to cast spells, allowing a new level of control never before possible in a Harry Potter game.' FROM games WHERE igdb_id = 3011 ON CONFLICT (game_id, language_code) DO NOTHING;
