INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trauma Center: New Blood', 'Keep your hands steady and your mind focused for Trauma Center: New Blood, sequel to Trauma Center: Second Opinion. This time around there''s a lot more on the line, as every cut of the scalpel, every pinch of the forceps, each and every second that ticks by is of the absolute greatest importance. If you think it''s too much to handle alone, invite a friend to assist with the operation and work together to save patients from flat lining.' FROM games WHERE igdb_id = 1525 ON CONFLICT (game_id, language_code) DO NOTHING;
