INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Golden Compass', 'The Golden Compass is an action-adventure/puzzle game played from a third-person perspective. It was released prior to the film by the same name and features a slightly different sequence of events towards the end of the story, as well as additional footage at the end of the game not seen in the film.' FROM games WHERE igdb_id = 4892 ON CONFLICT (game_id, language_code) DO NOTHING;
