INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Rush Adventure', 'Sonic returns to the DS with all the classic 2D dual screen action of "Sonic Rush," as well as a new high-seas adventure where he clashes with ruthless pirates. As Sonic, set off from Windmill Village to explore seven islands for action-packed adventures spread across a large map. As you venture, you''ll uncover valuable items and materials that will help Tails build new ships so that Sonic can track down the villainous pirates in a variety of ways.' FROM games WHERE igdb_id = 19261 ON CONFLICT (game_id, language_code) DO NOTHING;
