INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spongebob Boo or Boom', 'A browser flash game where the player control SpongeBob, Patrick, Sandy, or Squidward to set plumsters in the neighborhood to blast away the Plank-O-Lanterns. Doing so turns the tiles into your character''s color. Get the most candy points before the end of the level to win!' FROM games WHERE igdb_id = 307863 ON CONFLICT (game_id, language_code) DO NOTHING;
