INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool Party', 'Grab your stick and go head-to-head in Pool Party for the Nintendo Wii system. With 13 different types of pool, including 9-Ball, 8-Ball, Rotation, Black Jack and Snooker, there''s a game of billiards to satisfy any pool shark where you will be hustlin'' pros in dive bars, honky-tonks, mansions and even yachts. Pool Party includes competitors with intelligent AI and tables with real-world physics.' FROM games WHERE igdb_id = 5103 ON CONFLICT (game_id, language_code) DO NOTHING;
