INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Shots Golf: Out of Bounds', 'The fun, addicting and ever-popular Hot Shots Golf franchise, tees it up on the PLAYSTATION 3 system. High Definition) detail of course graphics accompanied with new, more accurate golf physics, brings a revolutionary new level of immersion to the already established signature style of pick-up and play gameplay. With vibrant new courses, zany new characters and a wealth of new online features, Hot Shots Golf: Out of Bounds strives to enter the next generation strokes ahead of the competition.' FROM games WHERE igdb_id = 154692 ON CONFLICT (game_id, language_code) DO NOTHING;
