INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: The Arcade', 'Silent Hill: The Arcade is an arcade game based on the Silent Hill series. Being a rail shooter, the game is a large departure from the normal survival horror mechanics. Gameplay is similar to the House of the Dead series in which players use light guns to aim and shoot at enemies. Shooting away from the screen reloads the player''s gun. The Arcade has a multiplayer element, a second player can join the game at any time.' FROM games WHERE igdb_id = 12075 ON CONFLICT (game_id, language_code) DO NOTHING;
