INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal Tournament III: Black Edition', 'The Black Edition is a complete Unreal Tournament III package -- included is the complete UT3 (with patch 2.0) as well as the Titan Pack. The “Titan Pack” gives players a substantial amount of enhanced features and new content, including many original environments, new gametypes, the namesake Titan mutator, powerful deployables and weapons, new characters, and the Stealthbender vehicle.' FROM games WHERE igdb_id = 46624 ON CONFLICT (game_id, language_code) DO NOTHING;
