INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Paper Mario', 'The newest chapter of the Paper Mario story isn''t just out of this world... it''s out of this dimension. What at first glance appears to be a 2D side-scroller ripped straight from the stylized pages of the Paper Mario universe soon turns into a hilarious dimension-shifting platformer possible only on Wii.' FROM games WHERE igdb_id = 2191 ON CONFLICT (game_id, language_code) DO NOTHING;
