INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Supernova 2', 'The hottest revolution and bestselling video game in the music game category explodes onto the dance floor with Dance Dance Revolution SuperNOVA2, the follow-up to 2006''s biggest and best DDR game to date! Dance Dance Revolution SuperNOVA2 will deliver a dance party extravaganza with its fun interactive gameplay, incredible song selection and innovative new game modes.' FROM games WHERE igdb_id = 6780 ON CONFLICT (game_id, language_code) DO NOTHING;
