INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix at the Olympic Games', 'The game follows Asterix, Obelix and the faithful Dogmatix as they travel to Greece in aid of their lovesick friend Alafolix. Their journey takes them to the Olympic Games where they find themselves pitted against the athletic might of the Roman Empire. Adventure and hilarity ensue as Asterix and friends compete to get the better of Brutus, his muscle-bound champion, and their long-time nemesis, Julius Caesar himself.' FROM games WHERE igdb_id = 4681 ON CONFLICT (game_id, language_code) DO NOTHING;
