INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gran-turismo-5-prologue', 1599, '2007-12-13', 82, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20bj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8jls.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo 5 Prologue', 'Gran Turismo 5 Prologue is a precursor and sampling of Gran Turismo 5 and replaced Gran Turismo HD Concept. The "Prologue" suffix is a self-reference to Gran Turismo 4 Prologue, which was released one year before the full version of Gran Turismo 4. Since October 3, 2008, the game is now referred to as Gran Turismo 5 Prologue Spec III which is the software''s version 3.0 title. Gran Turismo 5 Prologue Spec III features 16-player online races, over 70 cars (including tuned cars), 6 tracks, 12 layouts, a 60 frames per second frame rate (during races, replays are displayed at 30 frames per second) and LPCM 7.1ch high definition sound.' FROM games WHERE igdb_id = 1599 ON CONFLICT (game_id, language_code) DO NOTHING;
