INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meet-the-robinsons--1', 3884, '2007-03-27', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cwo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar108h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet the Robinsons', 'The game follows Wilbur through 40 missions and 6 different locales, a few of which are revisited in the movie. Secret Blueprints allow the player to "build" different Cheats and Extras, using Cornelius Robinson''s Transmogrifier. This machine creates items using Base Components which Wilbur collects during his adventure. A Breakout like game called Chargeball is both featured in the game itself and as an extra gameplay option. Different Chargeball "maps" can be found throughout game and it is up to Wilbur to become the Chargeball champion.' FROM games WHERE igdb_id = 3884 ON CONFLICT (game_id, language_code) DO NOTHING;
