INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karaoke Revolution Presents: American Idol', 'Karaoke Revolution Presents American Idol combines the highly acclaimed Karaoke Revolution game engine with America’s most popular television show to deliver an authentic Idol experience for the PlayStation 2. Sing along to 40 new songs, including hits from the show, and compete from auditions to performances on center stage in your quest to become the next American Idol.
