INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aquadelic-gt', 17807, '2007-02-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vt2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ebcwaxlngxkklsnwgcmq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquadelic GT', 'Aquadelic GT is a boat racing game in the style of a kart racer – easy to learn, but challenging to master. Enjoy piloting boats with stunning physics. Whilst one is stable in every situation another can be hard to control at speed. There are multiple paint-jobs for each boat, so you can choose one you like. It is also possible to control bigger vessels like yachts and cargo ships for relaxing leisure cruises. And one more thing... Use torpedoes, rockets, mines and even jumping frogs to smash your opponents.' FROM games WHERE igdb_id = 17807 ON CONFLICT (game_id, language_code) DO NOTHING;
