INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raft Wars', 'Raft Wars is a popular flash game from the late 2000s. It is a strategic shooter game similar to the popular mobile game Angry Birds. As the end of support for flash happened at the end of 2020, the developer and his team ported the game to the most advanced web platform HTML5 and released it on late 2019.' FROM games WHERE igdb_id = 143569 ON CONFLICT (game_id, language_code) DO NOTHING;
