INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadowrun', 'Shadowrun is a first-person shooter introducing mild cyberpunk elements to the gameplay. The game takes place in Brazil in the year 2031: before the events that shaped the Shadowrun universe. The player chooses between two factions to play as: The megacorp RNA Global, and the resistance group known as The Lineage. Playable races are Human, Elf, Troll, and Dwarf. Each race has their own unique racial traits.' FROM games WHERE igdb_id = 7643 ON CONFLICT (game_id, language_code) DO NOTHING;
