INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supreme Commander: Forged Alliance', 'Forged Alliance is a stand-alone expansion to the critically acclaimed RTS game Supreme Commander. The game adds a brand new alien race, the Seraphims, who have come back from outer space to wreak havoc on humanity. One campaign had been added, and the gameplay of the three existing factions has been significantly reworked.' FROM games WHERE igdb_id = 888 ON CONFLICT (game_id, language_code) DO NOTHING;
