INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Fantasia', 'From the makers of the Guilty Gear series of fighting games comes Battle Fantasia, a 2D fighter with lively 3D backgrounds, cel-shaded graphics, and fantasy-themed characters. In addition to traditional Arcade, Versus, Time Attack, and Practice modes, Battle Fantasia also features a Story mode that provides RPG-style dialogue and detailed information about the lives of each of the ten main fighters. Gamers must learn to master counterattacks and the energy-gauge depleting Heat mode in order to advance through scenarios and unlock hidden illustrations, but those simply looking for a quick battle can also head online for head-to-head matches against a friend.' FROM games WHERE igdb_id = 5499 ON CONFLICT (game_id, language_code) DO NOTHING;
