INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Wanna Be the Guy', 'I Wanna Be the Guy: The Movie: The Game is a 2D platform indie freeware video game created by independent developer Michael "Kayin" O''Reilly for Microsoft Windows using Multimedia Fusion 2. First released in October 2007, the game is not in active development despite being listed as a beta, though the source code for the game was released by Kayin in November 2011.
