INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hour of Victory', 'Hour of Victory allows you to play a key role in the pivotal and cinematic battles from the European and North African theaters of World War II, using the skills and gameplay style you choose. Sneak into enemy territory as a covert operative, storm the gates as a British Commando, or snipe from afar as an Army Ranger - each character''s unique attributes will be needed for the fulfillment of the overall objective. Only with all these skills working closely together will you be able to say that you helped define the Hour of Victory.' FROM games WHERE igdb_id = 7011 ON CONFLICT (game_id, language_code) DO NOTHING;
