INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crisis Core: Final Fantasy VII', 'In CRISIS CORE, players can experience the D.M.W (Digital Mind Wave) system, which enhances the real-time battle system, allowing players to unleash special attacks or call upon various FINAL FANTASY summons. Players can also witness graphics and CG cutscenes coupled with voice acting in a 16:9 widescreen presentation, made possible by the PSP system hardware.' FROM games WHERE igdb_id = 2407 ON CONFLICT (game_id, language_code) DO NOTHING;
