INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viva Piñata: Party Animals', 'A multiplayer game expanding the Viva Pinata experience. Compete in a variety of zany battles and races in the social party game Viva Piñata: Party Animals. Control the fame, fortune, and destiny of all your favorite characters from Viva Piñata: Fergy Fudgehog, Paulie Pretztail, Franklin Fizzlybear, and Hudson Horstachio. It''s party time!' FROM games WHERE igdb_id = 7237 ON CONFLICT (game_id, language_code) DO NOTHING;
