INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BioShock', 'BioShock is a horror-themed first-person shooter set in a steampunk underwater dystopia. The player is urged to turn everything into a weapon: biologically modifying their own body with Plasmids, hacking devices and systems, upgrading their weapons, crafting new ammo variants, and experimenting with different battle techniques are all possible. The game is described by the developers as a spiritual successor to their previous PC title System Shock 2. BioShock received high praise in critical reviews for its atmospheric audio and visual quality, absorbing and original plot and its unique gaming experience.' FROM games WHERE igdb_id = 20 ON CONFLICT (game_id, language_code) DO NOTHING;
