INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Syphon Filter: Logan''s Shadow', 'Syphon Filter: Logan''s Shadow is a third-person shooter developed by Bend Studio and published by Sony Computer Entertainment. Released in October 2007 for the PlayStation Portable (PSP), it is the sixth instalment in the Syphon Filter series. The game follows secret agent Gabe Logan as he embarks on a mission to recover a stolen weapon of mass destruction, while dealing with betrayal and uncovering a deeper conspiracy.' FROM games WHERE igdb_id = 19430 ON CONFLICT (game_id, language_code) DO NOTHING;
