INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Online: Duel Evolution', 'Yu-Gi-Oh! Online: Duel Evolution was a major update from "Yu-Gi-Oh! Online", that changed many aspects of the game. Players now have their own avatars and can explore portions of Domino City from the original Yu-Gi-Oh! series and the Duel Academy from the Yu-Gi-Oh! GX series. The dueling screen and the Deck editor have also been redesigned and improved.
