INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest Swords: The Masked Queen and the Tower of Mirrors', 'Developed from the ground up to take advantage of the Wii and its motion-sensing technology, Dragon Quest Swords: The Masked Queen and the Tower of Mirrors is set to slice its way onto Nintendo''s next-generation platform. This exclusive title utilizes the Wii''s motion-sensing controls as players use the Wii Remote to slash, parry and blast their way through a land filled with trademark Dragon Quest foes. Developed with both longtime fans and casual players in mind, Dragon Quest Swords: The Masked Queen and the Tower of Mirrors is poised to take video gaming to an entirely new level of fun and interaction.' FROM games WHERE igdb_id = 1822 ON CONFLICT (game_id, language_code) DO NOTHING;
