INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burnout-dominator', 6203, '2007-03-06', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pmo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/q2vp20zm1pw4zbure3fy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burnout Dominator', 'Burnout Dominator is an installment of the Burnout series for the PlayStation 2 and the PlayStation Portable systems. The game is mainly focused on returned Burnouts feature - draining a complete boost meter without stopping wich was last seen in Burnout 2: Point of Impact. With return of Burnouts feature there were four new game modes added including Maniac Mode (players need to drive dangerously to get highest scores by earning drifts, air, oncoming and near misses. Chaining Burnouts in this mode increases the score multiplier), Drift Challenge (in this mode player need to obtain as many feet of drifting as possible. Chaining Burnouts also increases the score multiplier here), Near Miss Challenge (same as Drift Challenge, but player needs to score near miss bonuses), Burnout Challenge (also same as Drift Challenge, but focusing on obtaining Burnouts score). However, some options have been removed from the game - for instance Burnout Dominator doesn''t feature Crash Mode, there is also no Traffic Checking Mode and Online Multiplayer. But PSP version features Burnout HQ where you can upload you score and download new track. The game consists of 12 different tracks, in 8 different real world locations. Each track has a forward and a reverse configuration.' FROM games WHERE igdb_id = 6203 ON CONFLICT (game_id, language_code) DO NOTHING;
