INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimCity Societies', 'Featuring an all-new, revolutionary feature set, SimCity Societies allows players to create their own kinds of cities, shape their cultures, societal behaviors and environments. Build an artistic city, an Orwellian city, futuristic city, green city, spiritual community or any society you want! With more accessible and innovative choices than before, SimCity Societies is the most versatile city building game.' FROM games WHERE igdb_id = 1491 ON CONFLICT (game_id, language_code) DO NOTHING;
