INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elona', 'Elona is a roguelike game created by Japanese developer Noa. Its name is short for "Eternal League of Nefia". Noa began developing Elona in 2006, and based it on roguelikes such as Ancient Domains of Mystery (ADOM) and Angband. Noa had previously made two other role-playing games, Shade and Etherwind. A reviewer at Insert Credit praised Elona as "very well-made" and compared its character development system to that of ADOM.' FROM games WHERE igdb_id = 50403 ON CONFLICT (game_id, language_code) DO NOTHING;
