INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrillville: Off the Rails', 'Thrillville: Off the Rails is a theme park simulation game developed by Frontier Developments and released in 2007. Players design and manage amusement parks while also riding attractions and playing mini-games. The game allows roller coasters to be built with fewer restrictions, encouraging more experimental designs. A story-driven campaign features characters and challenges set across different themed parks' FROM games WHERE igdb_id = 209 ON CONFLICT (game_id, language_code) DO NOTHING;
