INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-rub-a-dub', 13560, '2007-04-05', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zkd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wrpvu6ugbxjggi3fev0r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Rub ''a'' Dub', 'Super Rub ''a'' Dub stars the yellow duck from technical demos known as Ducks demo for the PlayStation 3 originally used at E3 2005 and 2006. Using the motion-sensing SIXAXIS controller, the player tilts a bathtub filled with water to move a rubber duck around the tub. There are many pitfalls to avoid, such as jumping out of the tub and toy sharks which will try to eat the smaller ducks. Online leaderboards track users fastest times, and allow users to see the replays of those fastest times. The game has three levels: fun, tricky, and tough. Each of these levels has 20 tubs that one needs to beat to proceed to the next level.
