INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nicktoons: Attack of the Toybots', 'The evil Professor Calamitous is at it again, but this time he’s gone too far. He has created evil robots that look just like our Nicktoons heroes. Now, SpongeBob, Jimmy Neutron, Danny Phantom, Timmy Turner, and Tak must stop them and the Professor no matter what it takes. By using new attacks, and awesome mech suits, now you can help our heroes stop the evil professor before he wreaks havoc everywhere.' FROM games WHERE igdb_id = 2774 ON CONFLICT (game_id, language_code) DO NOTHING;
