INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('csi-hard-evidence', 4782, '2007-09-25', 47, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ykg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hnvnalb8an4vchgprqb7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CSI: Hard Evidence', 'CSI: Hard Evidence continues the crime-solving experience of Ubisoft’s CSI video game series. Players join Gil Grissom, Catherine Willows and the rest of the Las Vegas cast to help solve crimes using realistic techniques and lab equipment. CSI: Hard Evidence features forensic reconstructions and atmospheric crime scenes taken directly from the television show, including an all-new garage lab for analyzing large evidence such as cars and boats, improved evidence gathering, review and lab mini-games, and more areas to explore, resulting in longer play experiences. CSI: Hard Evidence is a whole new game that’s all about the evidence and even more like the show, giving fans the experience of being part of the CSI Vegas team. CSI: Hard Evidence includes multiple methods of evidence recovery, crime reconstructions, and all-new high-tech forensic gadgets so fans can feel like real crime scene investigators.' FROM games WHERE igdb_id = 4782 ON CONFLICT (game_id, language_code) DO NOTHING;
