INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy: 20th Anniversary Edition', 'This is an enhanced version version of the original Final Fantasy, with higher resolution 2D graphics now in 16:9, FMV sequences, a re-recorded higher quality soundtrack, along with all the new dungeons and revised script from the Dawn of Souls Gameboy Advance port that came before it. As a bonus, it also includes art galleries of Yoshitaka Amano''s illustrations.' FROM games WHERE igdb_id = 397 ON CONFLICT (game_id, language_code) DO NOTHING;
