INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Osher Bli Gvulot', 'Osher Bli Gvulot is the first full-length Israeli adventure game created with AGS. It contains 10 hours of gameplay with 2 hours of original music and voice speech. The game''s hero is Osher, a 30-yo Israeli guy trying to get elected as Israel''s next prime minister.
