INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA March Madness 07', 'The NCAA Basketball (formerly NCAA March Madness) series was a College basketball game which was published by EA Sports from 1998 until 2009. After EA Sports'' rival publisher 2K Sports cancelled its own college basketball game, College Hoops, in 2008, EA changed the name of the series from NCAA March Madness to NCAA College Basketball. The series was discontinued on February 10, 2010.[1]
