INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carcassonne', 'Carcassonne starts with a single terrain tile face up and 71 others shuffled face down for the players to draw from. On each turn a player draws a new terrain tile and places it adjacent to tiles that are already face up. The new tile must be placed in a way that extends features on the tiles it abuts: roads must connect to roads, fields to fields, and cities to cities.
