INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle vs. Chess', 'Commanders, assemble your armies! BATTLE vs. CHESS calls for an interactive feather duster, chartering the successful chess game principle into the present day multimedia world. Animated fantasy figurines assemble in magical worlds and await your command! As a Commander, execute skillful maneuvers on the game board and catapult yourself directly into the battle with devastating attacks, chessman vs. chessman.' FROM games WHERE igdb_id = 177076 ON CONFLICT (game_id, language_code) DO NOTHING;
