INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms: Open Warfare 2', '"Worms: Open Warfare 2 features a ton of single player content, new multiplayer modes like Forts mode and Race mode and of course you can customize teams and schemes to your heart’s content. On Nintendo DS the gameplay takes place spread over both screens, there is full support for all wireless modes including Nintendo Wi-Fi Connection and the included landscape and flag editors are designed specifically for touch screen use.
