INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('donkey-kong-barrel-blast', 4817, '2007-06-28', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wfc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5iyx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Barrel Blast', 'Donkey Kong Barrel Blast is a racing game where the player can handle the selected character using the Wii Remote and Nunchuk, replacing the DK Bongos that initially were to be used. To speed the player must shake the Wii Remote and Nunchuk simultaneously, lift them to jump and use the motion sensor to beat rivals and obstacles and using items, while the character will be guided by the route of the tracks, including curves of automatic. Players can learn to race at Cranky''s flight school where Cranky gives 8 lessons on how to play the game, acceleration, use of elements and Wild Move.' FROM games WHERE igdb_id = 4817 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 4817 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
