INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Layton and the Curious Village', 'In the curious village of St. Mystere, townsfolk speak to each other in riddles, lock their doors with sliding puzzles and hide their secrets within brainteasers. When a wealthy baron passes away, his will reveals an elusive treasure hidden someplace inside the village. Now it''s up to Professor Layton to untangle St. Mystere''s riddles and puzzles, find the hidden treasure, and crack the case.' FROM games WHERE igdb_id = 1397 ON CONFLICT (game_id, language_code) DO NOTHING;
