INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('recettear-an-item-shops-tale', 12524, '2007-12-21', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jkp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qcjc5xk40xmlo4br2lw7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recettear: An Item Shop''s Tale', 'Recettear is the story of an item shop, the girl who lives in it, and the fairy who turned her life upside down. Recette Lemongrass finds herself in charge of an item shop built into her house, in order to pay back a loan her father took and then skipped out on - and Tear, her newfound fairy "companion", won''t take no for an answer! As Recette, you have to decide how you''ll get your stock - either through playing the markets in town or going out into the wild with an adventuring friend and thrashing beasts until they give up the goodies - how much to sell things for, what the shop should look like, and how to best go about getting the money Tear needs to pay off the loan. If you can''t come up with the money... well, hope you like living in a cardboard box.' FROM games WHERE igdb_id = 12524 ON CONFLICT (game_id, language_code) DO NOTHING;
