INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellgate: London', 'Hellgate: London combines the depth of role-playing games and action of first-person titles, while offering infinite playability with randomly created levels, items and events. The player creates a heroic character, completes quests and battles through innumerable hordes of demons to advance through experience levels and branching skill paths. A robust, flexible skill and spell system, highly customizable appearances and a massive variety of randomly generated equipment allow players to create their own unique hero.' FROM games WHERE igdb_id = 325 ON CONFLICT (game_id, language_code) DO NOTHING;
