INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Europa Universalis III', 'Europa Universalis III delves deeply into the areas of exploration, trade, warfare and diplomacy. This epic strategy game lets players take control of a nation and guide it through the ages to become a great global empire. Unparalleled in its depth and historical accuracy, Europa Universalis III gives the player unprecedented freedom in how they choose to rule their nation from an impressive choice of over 250 historically accurate countries.' FROM games WHERE igdb_id = 683 ON CONFLICT (game_id, language_code) DO NOTHING;
