INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CivCity: Rome', 'CivCity: Rome, an innovative city builder, invites players to shift focus from building a multi-city empire and zoom-in on the great cities of the Roman Empire, culminating in Rome itself! Through dozens of missions, each offering an array of interesting decisions, players will be charged with building, nurturing and managing one of these great cities as they endeavor to lead the Roman Empire from its humble beginnings to its mighty apogee. Features players have enjoyed in the Civilization series, like research, city happiness, production and culture, can now be managed actively in the wonderfully immersive world of CivCity: Rome.' FROM games WHERE igdb_id = 3083 ON CONFLICT (game_id, language_code) DO NOTHING;
