INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witcher', 'Based on the novel series by Andrzej Sapkowski, The Witcher follows Geralt of Rivia, an amnesiac witcher (problem solver and slayer of monsters) whose home, the Kaer Morhen citadel, is besieged by an organization called the Salamandra, who steal their valuable potions and get away. Throughout the game, Geralt must resolve people''s moral dilemmas, connect the dots of his past and track down the Salamandra.' FROM games WHERE igdb_id = 80 ON CONFLICT (game_id, language_code) DO NOTHING;
