INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maelstrom-the-battle-for-earth-begins', 10134, '2007-02-20', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3tb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6vw5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maelstrom: The Battle for Earth Begins', 'In the space of fifty years, Earth changed from a planet on cusp of a challenging future to a world a breath away from lifelessness and plunged into an apocalyptic time of ecological disaster, global warfare and the meltdown of human civilization. This is the time of the Maelstrom. In this ravaged world, the planet''s dwindling resources have divided what remains of mankind in two: the urban freedom fighting ''Remnants'' and the technologically advanced ''Ascension''. Now they must wage war against a new threat, the invasion of a savage alien race, the Hai-Genti, and each other in a desperate struggle for supremacy and survival. Through the game''s missions, take command from different viewpoints and employ faction-specific tactics and weaponry to achieve your objectives. Complete with the ability to terraform landscapes and transform units, Maelstrom provides gamers with the power to harness the forces of nature in the most frantic, destructive, action-packed RTS game yet.' FROM games WHERE igdb_id = 10134 ON CONFLICT (game_id, language_code) DO NOTHING;
