INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Tomorrow War: Factor K', 'The computer game "Tomorrow is War: Factor K", created based on the original script by Alexander Zorich, continues the story told in the large-scale space simulator "Tomorrow is War" and the book trilogy of this famous science fiction writer ("Tomorrow is War", "Without Mercy", "Time is Moscow!").' FROM games WHERE igdb_id = 72245 ON CONFLICT (game_id, language_code) DO NOTHING;
