INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Izuna 2: The Unemployed Ninja Returns', 'Ichika, a fisherwoman from the previous game, has plans to get married. However, during the night before Ichika''s marriage, Shino, Izuna''s best friend, disappears. Izuna frantically tries to find her and quickly locates her. Shino reveals that she was searching for her sister, Shizune, so Izuna and her friends decide to help Shino find Shizune.' FROM games WHERE igdb_id = 21345 ON CONFLICT (game_id, language_code) DO NOTHING;
