INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: The Dracula X Chronicles', 'Castlevania: The Dracula X Chronicles is an entirely new take at the best Castlevania game to never be released in the US, "Castlevania: Rondo of Blood". The Dracula X Chronicles brings this action/adventure franchise to the PSP system for the first time, complete with 3D graphics, enhanced gameplay and new music. Completing the Dracula X storyline, this game also includes an unlockable version of Symphony of the Night and players will also be able to unlock the original Rondo of Blood from the NEC PC Engine. Includes unlockable versions of the original "Rondo of Blood" and "Symphony of the Night" games, optimized for the PSP. Timeless side scrolling action through more than 10 gothic stages and additional hidden areas. Return to previously completed levels to find additional secrets.' FROM games WHERE igdb_id = 21888 ON CONFLICT (game_id, language_code) DO NOTHING;
