INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boing! Docomodake DS', 'Boing! Docomodake is a platform action game based on the mascot of Japanese mobile phone company, NTT Docomo. In the game, you play as Papa Docomodake and guide him through obstacles to help him find the members of his missing family. Strategy and finesse, mixed with a little action and adventure make Boing! Docomodake a fun and interactive game that will entertain the masses for hours!' FROM games WHERE igdb_id = 21473 ON CONFLICT (game_id, language_code) DO NOTHING;
