INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocky Balboa', 'Rocky Balboa is a 2007 video game based on the movie of the same name for the PlayStation Portable, which is similar in style and content to Rocky Legends. The game includes footage from each Rocky film, showing the buildup to the major fights of the film series. There are also some flashback videos of the training footage from the films (this is used in the Mickey''s Corner section of the game, which is a tutorial aimed to teach new players how to play).' FROM games WHERE igdb_id = 23112 ON CONFLICT (game_id, language_code) DO NOTHING;
