INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Itadaki Street DS', 'Itadaki Street DS is a Monopoly-like game that has some Mario Party-esque elements added to it due to the appearance of several Mario characters (minigames, for example). Players move around the board, buying shops and collecting money from others who land on their shop spaces. Depending on circumstances, some players can forcibly take over another player''s shop spaces, or make them inactive for a turn. Players can also hold shares of a block of spaces so that they get paid when someone lands on any space in that block, even if it is not their own.' FROM games WHERE igdb_id = 71885 ON CONFLICT (game_id, language_code) DO NOTHING;
