INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'America''s Army: True Soldiers', 'America''s Army: True Soldiers is a first-person shooter video game developed by Red Storm Entertainment and published by Ubisoft. It was released on November 15, 2007. It is a spin-off of the United States Army''s computer game America''s Army. Unlike the original America''s Army, this game is not freeware.' FROM games WHERE igdb_id = 5482 ON CONFLICT (game_id, language_code) DO NOTHING;
