INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Balloon Pop', 'The infamous Balloon Thief has stolen the Earth''s precious seasons and sealed them away in his magical balloons. It is up to you to release the magic stored inside and bring life back to your planet one season at a time! Point at the screen to aim and link a series of balloons to create satisfying combos! Watch as the seasons change and bring the planet back to life, releasing different graphical elements to represent each month.' FROM games WHERE igdb_id = 4704 ON CONFLICT (game_id, language_code) DO NOTHING;
