INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayola Treasure Adventures', 'The perfect game for all creative and adventurous boys and girls, Crayola Treasure Adventures asks the explorer to color, draw, and think their way through numerous exotic locations, challenging puzzles, and exciting adventures. Crayola Treasure Adventures also offers a digital coloring book that lets the young artist run wild with their imagination through more than a hundred different digital crayons and pictures that the young artist may color. Crayola Treasure Adventures truly epitomizes the art of childhood by offering a creative escape for any young explorer or artist on their Nintendo DS!' FROM games WHERE igdb_id = 21363 ON CONFLICT (game_id, language_code) DO NOTHING;
