INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Screwjumper!', 'Freefall into the depths of the chaotic underworld as a Screwjumper, and drive the aliens back to their home world by destroying their precious mining equipment. Demolish structures in freefall as you increase your destructive power by increasing your velocity. Use dynamite to pick off hazards and high value targets. Destroy the mine core and jetpack out alive.' FROM games WHERE igdb_id = 21884 ON CONFLICT (game_id, language_code) DO NOTHING;
