INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summon Night: Twin Age', 'Reiha and Aldo grew up together as brother and sister on the tropical island of Jarazi, among a race of people with beast-like features. There they learned to commune with the Nature Spirits that surrounded them. One day, the Spirits began acting strangely, prompting Reiha and Aldo to investigate. Their quest to find out who or what is behind the corruption of the Spirits will lead them back to the human lands where the cataclysm first brought them together.' FROM games WHERE igdb_id = 21477 ON CONFLICT (game_id, language_code) DO NOTHING;
