INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JAM sessions', 'A guitar-playing Nintendo DS game.The Nintendo DS touch screen represents a guitar''s strings and the D-pad / buttons become the fingered chords. By "strumming" on the virtual strings you''ll play the chord that you''ve selected on the D-pad. The tool recognizes both up and down strums at half and full velocities, and you''ll hear the subtle changes to the chord in the different ways to play them.' FROM games WHERE igdb_id = 47925 ON CONFLICT (game_id, language_code) DO NOTHING;
