INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball FX', 'Pinball FX is a pinball machine video game for the Xbox 360. It was developed by Zen Studios and published by Microsoft Game Studios. It was released on April 25, 2007 via the Xbox Live Arcade service. The game features three tables, with six more available as downloadable content, leaderboards and online multiplayer. A sequel to the game, Pinball FX 2 was released on October 27, 2010.' FROM games WHERE igdb_id = 21915 ON CONFLICT (game_id, language_code) DO NOTHING;
