INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Beat That!', 'Sometimes, the biggest action comes in the smallest package! Get behind the wheel of any of 30 cars pulled straight from the Hot Wheels lineup. Race on 12 tracks built to scale - corkscrews, loops, shortcuts and hidden paths, chokepoints, and interactive elements - then battle on four different battlegrounds. Put the pedal to the metal in five different gameplay modes, including Race, Eliminator, Rampage, and Battle.' FROM games WHERE igdb_id = 4916 ON CONFLICT (game_id, language_code) DO NOTHING;
