INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gemsweeper', 'In Gemsweeper the player assumes the role of a treasure hunter. When working in a museum putting together the pieces of a broken Olmec statue, the statue becomes alive and asks the player and old professor McGuffog to rebuild the mystical city of El Dorado. By solving over 225 puzzles, the player gradually rebuilds the ruins of the city and progresses his treasure hunter rank.' FROM games WHERE igdb_id = 135284 ON CONFLICT (game_id, language_code) DO NOTHING;
