INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neves', 'Neves (ハメコミ LUCKY PUZZLE DS Hamekomi Rakkī Pazuru Dīesu?) is a puzzle game developed by Yuke''s Media Creations for the Nintendo DS, based on the Japanese Lucky Puzzle, a tangram-like dissection puzzle. In the game, players use the stylus to move, rotate and flip pieces on the DS''s touch screen to clear puzzles. It features over 500 different puzzles from which to choose. 
