INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons Tactics', 'Faithfully utilizing the Dungeons & Dragons 3.5 rule-set, Dungeons & Dragons: Tactics allows players to take a party of six adventurers into a wide variety of dangerous environments to experience deep and exciting turn-based action. All of the core races and classes are available to the player, including two Psionic classes, the Psion and the Psychic Warrior. Play with your friends wirelessly in both cooperative and adversarial game modes.' FROM games WHERE igdb_id = 23051 ON CONFLICT (game_id, language_code) DO NOTHING;
