INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EA Playground', 'EA Playground features various mini-games structured around a singleplayer "campaign" and a multiplayer party mode. All of the mini-games are based on well known playground games. These include Dodgeball, Tetherball, Slot car racing, paper airplane racing, dart shootout and wall ball. Also included is "Kicks", which is a mix of the sports Soccer and Volleyball (Sepak takraw). More games can be unlocked by progressing through the single player campaign.' FROM games WHERE igdb_id = 4825 ON CONFLICT (game_id, language_code) DO NOTHING;
