INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Jong', 'WordJong features simple, yet engrossing gameplay: Use a set of lettered tiles to create words, clearing the board as you use tiles. Shoot for high-scoring words, earn bonus tiles, and work to clear the board with no leftover letters. WordJong boasts several new features exclusive to the Nintendo DS system, including local and online wireless play as well as DS Download play, a variety of Solo Play modes, a 100,000+ word dictionary, full support for both the Control Pad and Touch Screen, and much, much more!' FROM games WHERE igdb_id = 47715 ON CONFLICT (game_id, language_code) DO NOTHING;
