INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid: Portable Ops Plus', 'A standalone expansion to Metal Gear Solid: Portable Ops, mainly focused on multiplayer. A single player mode called Infinity Mission was included, but has no story. There are also new missions and tutorials for beginners. With up to 6 players via WiFi, new characters including Old Snake from Metal Gear Solid 4, Roy Campbell, and Raiden from Metal Gear Solid 2, this game continues the trend of capturing and recruiting comrades.' FROM games WHERE igdb_id = 21617 ON CONFLICT (game_id, language_code) DO NOTHING;
