INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragoneer''s Aria', 'The world was at peace thanks to the six elemental dragons of water, fire, thunder, earth, wind, and ice. In this world, dragons control both nature and the climate; therefor they are worshipped by human beings and humanoids as the gaurdians of the world, and protected by those known as Dragoneers. When a black dragon suddenly appears and starts to destroy the land, it''s up to one young dragoneer to stop it with the help of his friends.' FROM games WHERE igdb_id = 24279 ON CONFLICT (game_id, language_code) DO NOTHING;
