INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Calling All Cars!', 'Calling All Cars is a high-octane, cops n'' robbers multiplayer, action/party game with cel-shaded graphics. The object of the game is to capture escaped convicts while battling against three other bounty hunters who are also trying to capture the criminals. Points are awarded for captured criminals, and the bounty hunter with the most points wins. The game features online multiplayer and split-screen play.' FROM games WHERE igdb_id = 20701 ON CONFLICT (game_id, language_code) DO NOTHING;
