INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Victorious Boxers: Revolution', 'Victorious Boxers: Revolution is a challenging, intense boxing title for the Wii. The first dedicated boxing title for the Wii, this game makes full use of its unique motion-control capabilities. Gameplay is realistic to appeal to sports and boxing fans, but also has an extensive Story Mode and many unique fighters with their own special moves, making it involving and easy to play for all audiences.' FROM games WHERE igdb_id = 5256 ON CONFLICT (game_id, language_code) DO NOTHING;
