INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('myst-online-uru-live', 21540, '2007-02-15', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rkv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/herc0fugn5sgr4ivrdpq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myst Online: URU Live', 'Myst Online: Uru Live is a massive multiplayer online game (MMOG) unlike anything else. Instead of repetitive kill/take/buy gameplay of other MMOGs, the very essence of Myst Online is to explore vast, fantastic worlds; savoring and uncovering new areas and new information at every turn. Exploring in Myst Online is an extraordinary experience, where immersing yourself in the environment gives you insight into how to move forward, and what went on before. You can explore alone, or share the journey with a select group friends or family from anywhere in the world. Create an online avatar and chat via text and voice, share images and clues, and explore the Ages of Myst Online together. You’ll rediscover, restore and rebuild the ancient city of D’ni and learn about the history of its fallen civilization.
