INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Front: Turning Point', 'The game is set in a fictional, alternate World War II in which Adolf Hitler is assassinated in the early days of the war, and under the new chancellor, Germany occupies Great Britain. Eventually, Nazi Germany is defeated, but this allows the Soviet Union to advance into Western Europe. The game features both real life and fictional "experimental" war machines and units.' FROM games WHERE igdb_id = 21239 ON CONFLICT (game_id, language_code) DO NOTHING;
