INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoo Hospital', 'You''ve graduated from veterinary college not a moment too soon! Your Aunt Lucy just called from the world famous Zoo Hospital she manages because she needs your help! A local property magnate, Gordon Grimm, is eyeing the zoo’s land as the potential site for a profitable mini-golf course. Under Aunt Lucy’s tutelage it’s now up to you to help restore the zoo to its former glory by treating its ailing inhabitants, improving its rating and attracting new exotic animals that will in turn attract the crowds!' FROM games WHERE igdb_id = 21220 ON CONFLICT (game_id, language_code) DO NOTHING;
