INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Puzzle', 'You''ll never think about word search puzzles the same way again. Word Puzzle takes a new spin on the classic game, plunging you into an action-packed arcade experience complete with combos, exploding word bombs, unique 3-D boards, achievements, and the chance to prove your textual superiority against other players. Five different game modes and frequently updated downloadable word packs give you nearly unlimited flexibility and excitement.' FROM games WHERE igdb_id = 21913 ON CONFLICT (game_id, language_code) DO NOTHING;
