INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants: Underpants Slam', 'SpongeBob SquarePants Underpants Slam! is a fast-paced, side-scrolling multiplayer slapstick collect ''em-up, set deep in the ocean. An incredibly powerful storm current has disrupted a Royal Laundry shipment of the undergarments of Neptune, Lord of the Sea, and has spread his unmentionables across the bottom of the ocean. Neptune now calls upon all the commonfish to collect his lost undergarments, and fix this "delicate" situation. He''s offered a bounteous reward to the sea creature who collects the most bloomers!' FROM games WHERE igdb_id = 2775 ON CONFLICT (game_id, language_code) DO NOTHING;
