INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Beat', 'Tank Beat is entirely stylus-based. As you draw tracks and fire on the DS''s bottom screen game map, your tank appears and responds on the top screen. Players engage in a variety of missions and commandeer a full range of tanks: from tiny scrappers, to missile carriers, to giant Panzers.' FROM games WHERE igdb_id = 21532 ON CONFLICT (game_id, language_code) DO NOTHING;
