INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of Mana', 'Breathing new life into the vaunted Mana franchise, Heroes of Mana takes the beloved series into an entirely new dimension. In the first real-time strategy title for the series, generals will plan, plot and strategize their way to victory on the battlefield. Command an army of heroes, creatures and beloved rabites with the use of the Nintendo DS Touch Screen, and experience an all-new perspective on the ever-evolving Mana saga. Players can see how they rank among others in the country by accessing the Heroes of Mana servers via the Nintendo Wi-Fi Connection.' FROM games WHERE igdb_id = 14990 ON CONFLICT (game_id, language_code) DO NOTHING;
