INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meteos: Disney Magic', 'The follow-up to one of the most critically-acclaimed Nintendo DS games to date, Meteos: Disney Magic combines the superb puzzle gameplay of the original version with beloved Disney brands. Featuring an original story within the classic Disney universe, players will be asked to help Jiminy Cricket and Tinker Bell in their quest to re-organize the famous Disney storybook vault after someone accidentally changed the stories.' FROM games WHERE igdb_id = 1166 ON CONFLICT (game_id, language_code) DO NOTHING;
