INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancient-wars-sparta', 19077, '2007-04-20', 48, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bq5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s6bgh5lst6ryogzpudml.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Wars: Sparta', 'Ancient Wars: Sparta is a real-time strategy game in which the player controls the Spartans, the Ancient Egyptians and the Ancient Persians. The game is divided up into three separate campaigns, one for each of the three cultures, with each campaign divided into multiple missions. The campaigns are independent of one another, and can be played in any order. The missions within each campaign, however, are linear, and each mission only becomes available when the previous one has been completed. Although gameplay focuses primarily on combat, the game also features elements of economic micromanagement, as the player must generate enough resources to build up their armies to the point where they can defeat the opposing forces. Within each mission, the player will usually have multiple primary objectives, and will often have one or more secondary objectives. Secondary objectives are not necessary to complete the mission, but often reward the player with troops and/or resources if fulfilled.' FROM games WHERE igdb_id = 19077 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 19077 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
