INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lair', 'In a world ravaged by endless conflict and natural disaster, a call for peace turns into a bloodbath of betrayal and deceit. Playing as a warrior riding a voracious dragon trained for deadly aerial and ground combat, and capable of scorching, clawing and smashing thousands of enemies, gamers must defeat countless armies to save a civilization. Together, the gamer and the beast will attempt to change the destiny of a world on the brink of extinction.' FROM games WHERE igdb_id = 7362 ON CONFLICT (game_id, language_code) DO NOTHING;
