INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar', 'The PlayStation 2 party classic comes to the PS3 in an updated and network rich upgrade. Anyone that is remotely interested in SingStar knows how the title operates - it turns your console into a modern day karaoke machine: Displaying the videos and music of some classic pop songs (it comes with around 30 initially), and presenting the words with which you and a few friends (or alone if that floats your boat) can accompany on the provided microphones.' FROM games WHERE igdb_id = 15180 ON CONFLICT (game_id, language_code) DO NOTHING;
