INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Chronicles', 'Set in a mystical world where mortal and fairy realms collide, the game tells the story of a mortal woman named Faye who is the only being able to awaken from a powerful fairy''s dream spell. She embarks on an adventure through a dream world to find her fairy husband and save her hometown. To solve the mystery, players must complete puzzles and search for clues leading to the whereabouts of Faye''s husband.' FROM games WHERE igdb_id = 21735 ON CONFLICT (game_id, language_code) DO NOTHING;
