INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wipeout Pulse', 'Wipeout Pulse is a racing game set in 2207, ten years after the events of Wipeout Pure. There are eight teams in Wipeout Pulse, with one ship available for each - although the player eventually gains the ability to change the appearance of their ships. Each ship has different characteristics; depending on the team chosen, its ship will vary in terms of handling, speed, acceleration and shield strength.' FROM games WHERE igdb_id = 1543 ON CONFLICT (game_id, language_code) DO NOTHING;
