INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Proving Ground', 'Tony Hawk''s Proving Ground features deeper customization than ever before, including a Video Editor with full-featured editing tools and visual effects for creating epic skate videos, and a fully customizable online Skate Lounge where players can skate with friends in the ultimate pad. In addition, players will have the freedom to skate from single player to online seamlessly, as well as utilize new gameplay mechanics such as skateable terrain altering and building, and Bowl Carving, delivering the most empowered skating experience ever. Tony Hawk-s Proving Ground also features even more Nail the Trick moves such as Nail the Grab and Nail the Manual intensifying the thrill of pulling off big tricks.' FROM games WHERE igdb_id = 2700 ON CONFLICT (game_id, language_code) DO NOTHING;
