INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyberpunk-the-arasakas-plot', 120199, '2007-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qje.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwlff.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberpunk: The Arasaka''s Plot', 'Cyberpunk: The Arasaka''s Plot is a mobile game based on Mike Pondsmith''s pen and paper RPG Cyberpunk. The game is a platformer similar to Flashback. The player can walk and run left and right, jump, crouch and climb ledges up and down. When entering combat the player uses a gun at long range or a melee attack at short range. Once enemies have been killed the player can take their armor and other items they might carry. Items that can be found include implants and new weapons. After taking damage, medic kits can be used to restore health. The player can hack various computer terminals he comes across. By doing so it''s possible to get access to weapon and stat upgrades and to unlock doors. The player might also come across links to the game''s website where more of its back story is revealed. Hacking involves playing a mini game that is similar to QIX. The game has some minor RPG elements although the player''s stats increase automatically as he progresses through the game. There are also implants that can be used to give the player an advantage through special abilities.' FROM games WHERE igdb_id = 120199 ON CONFLICT (game_id, language_code) DO NOTHING;
