INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UFO: Extraterrestrials', 'UFO: Extraterrestrials is a Microsoft Windows game aimed to be a spiritual sequel to the highly acclaimed UFO: Enemy Unknown (retitled X-COM: UFO Defense in North America). Developed by Chaos Concept, the game incorporates a twist of the aliens defeating the humans on Earth. The game takes place on a human-colonized planet named Esperanza, where the alien threat has just arrived.' FROM games WHERE igdb_id = 9437 ON CONFLICT (game_id, language_code) DO NOTHING;
