INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agatha Christie: Evil Under the Sun', 'Famous detective Hercule Poirot is back in typical style, turning up at just the right time to begin an investigation into the murder of a famous actress during what should have been the start of a relaxing holiday. Taking on the role of Hercule Poirot, players can scour a stunning tropical island for clues and delve deeper into the mysterious relationships between over 20 unique characters to search out the killer...' FROM games WHERE igdb_id = 4664 ON CONFLICT (game_id, language_code) DO NOTHING;
