INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phoenix-wright-ace-attorney-trials-and-tribulations', 1428, '2007-08-23', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z8u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lyskemijakvnqjskqjwr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phoenix Wright: Ace Attorney - Trials and Tribulations', 'Phoenix Wright: Ace Attorney − Trials and Tribulations (known as Gyakuten Saiban 3 in Japan) is the third game in the Ace Attorney series. Players take on the role of Phoenix Wright, a defense attorney known for taking on seemingly impossible cases. While the game focuses on a few specific cases, the overarching story of the Phoenix Wright franchise spans the length of the series, involving obscure characters from large families and intricate webs of lies, plots, and murder. The nature of the series remains generally lighthearted, something that''s reinforced by its playful, anime-inspired visual style, but the nature of the crimes committed can be cold and downright disturbing. While the game''s legal acumen is highly dubious, its aim seems to be more about producing comedic or stereotypically dramatic courtroom moments. Ace Attorney 3 makes light use of the DS touch screen, allowing the player to examine crime scenes and inspect evidence and character profiles. The top screen is used more for storytelling purposes, displaying various dialogue and conversations between characters. During these sequences the lower screen becomes a selection menu, displaying a series of questions to ask witnesses and further your investigation in search of evidence to use in defense of your client in each chapter.' FROM games WHERE igdb_id = 1428 ON CONFLICT (game_id, language_code) DO NOTHING;
