INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FreeStyle Street Basketball', 'FreeStyle Street Basketball (FSSB) is a massively multiplayer online sports game made by JC Entertainment and with cel-shaded graphics. It is a fast paced, arcade styled representation of half court streetball, self-described as being Hip-Hoop. Players team up with one another to challenge other online players to matches of basketball that are characterized by high tempo, freedom of movement, and a premium placed on synergy and teamwork. Players can also create clubs and enter club matches, play in a single player story mode, roam around in Open Court mode, drop and add skills as needed, and choose from millions of different outfits to express themselves due to the sheer quantity of wearable items in the ingame shop.' FROM games WHERE igdb_id = 21423 ON CONFLICT (game_id, language_code) DO NOTHING;
