INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Drive', 'Deer Drive for the Nintendo DS is the first game to bring the thrill of arcade action hunting to a handheld platform. Deer Drive for the NDS is fast, fun, and easy to play but hard to master. With 125 power-ups and upgrades, 30 levels and a ton of animals there''s plenty to see, do and shoot. But don''t get too relaxed - Dangerous animals like mountain lion, boar and bear are just waiting to take you down.' FROM games WHERE igdb_id = 47771 ON CONFLICT (game_id, language_code) DO NOTHING;
