INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Head Fred', 'In Dead Head Fred, players take on the persona of private detective Fred Neuman. Savagely murdered and then resurrected in a bizarre scientific experiment, Fred is without his memory or his head! The game immerses players in the vicious action as they collect, upgrade and switch heads on the fly to strategically fight malformed mutants, ghoulish gangsters, and maniacal mob bosses in a unique and compelling story of revenge and redemption.' FROM games WHERE igdb_id = 21047 ON CONFLICT (game_id, language_code) DO NOTHING;
